-- Parroquia y Nuestros fines pasan del texto de partida a su contenido.
--
-- Parroquia: la sede es Santa María Goretti (el texto de partida decía
-- «Parroquia de Nuestra Señora de los Desamparados… en el corazón de Málaga» y
-- nombraba un segundo titular que el Grupo no tiene). Lleva horarios y
-- despacho, el mapa, quiénes son los Pasionistas, una cita de San Pablo de la
-- Cruz y la parroquia en fechas. Los datos salen de la Diócesis de Málaga, de
-- la provincia pasionista y de la propia parroquia; el Grupo tiene que
-- confirmarlos.
--
-- Nuestros fines: los tres fines (culto, caridad y formación; antes solo dos),
-- cada uno con su tarjeta y su enlace, una cita y la llamada a hacerse hermano.
--
-- Solo se sustituye la página que sigue con el texto de partida: si alguien ya
-- la ha editado en el CMS, se queda como está.

UPDATE `ContenidoPagina` SET `datos` = '{"cabecera":{"titulo":"Parroquia - Pasionistas","subtitulo":"Santa María Goretti, nuestra sede canónica, y la comunidad pasionista que la atiende.","foto":"","fotoAlt":""},"bloques":[{"tipo":"texto","titulo":"","html":"<p>El Grupo Parroquial tiene su sede canónica en la <strong>Parroquia de Santa María Goretti</strong>, en la calle Corregidor Paz Guzmán, en el distrito de Cruz de Humilladero. Es una parroquia de barrio, de unos diez mil vecinos, y desde que se fundó la atiende una comunidad de <strong>Padres Pasionistas</strong>.</p><p>En ella celebramos nuestros cultos y en ella se reúne el Grupo durante el año. Aquí tienes sus horarios, cómo llegar y quiénes son los religiosos que nos acompañan.</p>"},{"tipo":"datos","titulo":"Horarios y despacho","presentacion":{"disposicion":"cuadricula"},"lineas":[{"etiqueta":"Misas de lunes a sábado","valor":"9:30 y 19:00 (en verano, 9:30 y 20:00)"},{"etiqueta":"Domingos y festivos","valor":"10:00 y 12:00"},{"etiqueta":"Confesiones","valor":"Antes de cada misa"},{"etiqueta":"Despacho parroquial","valor":"Martes y viernes, de 18:00 a 20:00"},{"etiqueta":"Teléfono","valor":"952 331 203"},{"etiqueta":"Correo","valor":"goretti@diocesismalaga.es"}]},{"tipo":"mapa","titulo":"Cómo llegar","presentacion":{"alto":"bajo","estilo":"oscuro"},"lugar":"Parroquia de Santa María Goretti","direccion":"C. Corregidor Paz Guzmán, 13, 29006 Málaga"},{"tipo":"texto","titulo":"Los Pasionistas","html":"<p>La Congregación de la Pasión de Jesucristo, cuyos religiosos firman con las siglas C.P., la fundó <strong>San Pablo de la Cruz</strong> en Italia, en el siglo XVIII. Su carisma es mantener viva la memoria de la Pasión de Cristo y anunciarla, sobre todo a quienes sufren.</p><p>Llegaron a Málaga en 1972, cuando el obispado erigió esta parroquia y se la encomendó. Desde entonces ha sido una comunidad abierta y volcada con los jóvenes, y su trabajo ha salido de la parroquia: capellanías de colegios y del cementerio, el Teléfono de la Esperanza, ejercicios espirituales y acompañamiento espiritual.</p><p>En el barrio sostienen Cáritas parroquial y el hogar del jubilado, la catequesis de niños, jóvenes y adultos, la preparación de bautizos y bodas y grupos como la Legión de María.</p>"},{"tipo":"cita","titulo":"","presentacion":{"estilo":"grande","alineacion":"centro"},"texto":"La Pasión de Jesús es la obra más grande y maravillosa del amor de Dios.","autor":"San Pablo de la Cruz","fuente":"Fundador de los Pasionistas"},{"tipo":"cronologia","titulo":"La parroquia en fechas","presentacion":{"disposicion":"vertical"},"hitos":[{"periodo":"1972","etiqueta":"Erección","titulo":"Nace la parroquia","relato":"En noviembre de 1972 el obispado erige la parroquia de Santa María Goretti y la encomienda a los Pasionistas, que acababan de llegar a Málaga.","foto":{"url":"","alt":"","pie":""},"tono":"ninguno"},{"periodo":"1973","etiqueta":"Río Baeza","titulo":"En unos bajos de la barriada","relato":"Todavía sin templo, la parroquia empieza a funcionar en unos locales de la calle Río Baeza. La inaugura el obispo Ángel Suquía el 3 de junio de 1973.","foto":{"url":"","alt":"","pie":""},"tono":"ninguno"},{"periodo":"1981","etiqueta":"El templo","titulo":"Una iglesia sin columnas","relato":"A finales de 1981 terminan las obras del templo, del arquitecto Verdú: una estructura triangular sin columnas, con forma de concha y lucernas circulares.\\n\\nLo bendice el obispo Ramón Buxarráis en diciembre de 1982.","foto":{"url":"","alt":"","pie":""},"tono":"oro"},{"periodo":"1997","etiqueta":"Retablo","titulo":"Un retablo nuevo","relato":"Se remodela el retablo y se incorpora nueva imaginería.","foto":{"url":"","alt":"","pie":""},"tono":"ninguno"},{"periodo":"2008","etiqueta":"Dedicación","titulo":"La dedicación del templo","relato":"Tras renovar en 2007 la cubierta, el suelo y la iluminación, el obispo Antonio Dorado Soto dedica solemnemente el templo el 12 de abril de 2008. La fecha se recuerda cada año.","foto":{"url":"","alt":"","pie":""},"tono":"granate"},{"periodo":"2011","etiqueta":"Imágenes","titulo":"San Gabriel y Santa María Goretti","relato":"Llegan al templo las imágenes de San Gabriel de la Dolorosa, santo pasionista, y de Santa María Goretti, titular de la parroquia.","foto":{"url":"","alt":"","pie":""},"tono":"ninguno"}]},{"tipo":"botones","titulo":"","presentacion":{"alineacion":"centro"},"botones":[{"texto":"Agenda de cultos","enlace":"/agenda","estilo":"principal"},{"texto":"Historia del Grupo","enlace":"/historia","estilo":"secundario"}]}]}'
WHERE `slug` = 'parroquia' AND `datos` LIKE '%La Parroquia de Nuestra Señora de los Desamparados, atendida por la Congregación de la Pasión%';

UPDATE `ContenidoPagina` SET `datos` = '{"cabecera":{"titulo":"Nuestros fines","subtitulo":"Culto, caridad y formación: para qué existe el Grupo Parroquial.","foto":"","fotoAlt":""},"bloques":[{"tipo":"texto","titulo":"","html":"<p>Como toda hermandad, el Grupo Parroquial existe para tres cosas que no se entienden por separado: dar <strong>culto</strong> a Dios y honrar a su Madre en la advocación de los Desamparados, vivir la <strong>caridad</strong> con quienes hoy se sienten solos o sin amparo, y <strong>formarse</strong> en la fe para vivirla con sentido.</p><p>La salida procesional es lo que más se ve, pero es solo una parte. El resto del año el Grupo reza, ayuda y aprende, y cualquiera puede sumarse.</p>"},{"tipo":"tarjetas","titulo":"","presentacion":{"columnas":"3","estilo":"contorno","alineacion":"izquierda"},"tarjetas":[{"titulo":"Culto","descripcion":"La eucaristía, el triduo, el besamanos y el rosario por el barrio: los momentos en que el Grupo se reúne ante su Titular.","enlace":"/cultos","icono":"iglesia"},{"titulo":"Caridad","descripcion":"La ayuda a quien la necesita, desde la parroquia y con lo que aportan los hermanos.","enlace":"/nuestros-fines/caridad","icono":"corazon"},{"titulo":"Formación","descripcion":"Catequesis, charlas y encuentros para crecer en la fe y entender lo que celebramos.","enlace":"/nuestros-fines/formacion","icono":"libro"}]},{"tipo":"cita","titulo":"","presentacion":{"estilo":"grande","alineacion":"centro"},"texto":"Venid a mí todos los que estáis cansados y agobiados, y yo os aliviaré.","autor":"Jesús","fuente":"Evangelio según san Mateo, 11, 28"},{"tipo":"llamada","titulo":"","texto":"Si quieres vivir todo esto desde dentro, hazte hermano del Grupo Parroquial.","boton":"Hazte hermano","enlace":"/hazte-hermano"}]}'
WHERE `slug` = 'nuestros-fines' AND `datos` LIKE '%se propone, como fines esenciales, la práctica de la caridad%';
